SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2015.YEAR, Станции2015.NUST, Станции2015.nr, Станции2015.E, Станции2015.EOTP, Станции2015.EURT, Станции2015.EUST, Станции2015.Q, Станции2015.TURT, Станции2015.TUST, Станции2015.B, Станции2015.GAZ, Доп_угли2015.gazpp, Станции2015.MAZUT, Станции2015.TORF, Станции2015.SLAN, Станции2015.PROCH, Станции2015.UGOL, Станции2015.DON, Станции2015.PODM, Станции2015.PECH, Доп_угли2015.intin, Доп_угли2015.vork, Станции2015.ARKT, Станции2015.KUZN, Доп_угли2015.kuzngd, Доп_угли2015.kuznt, Доп_угли2015.kuznss, Доп_угли2015.kuznun, Станции2015.URAL, Доп_угли2015.sver, Доп_угли2015.chel, Доп_угли2015.kizel, Станции2015.BASHK, Станции2015.KAZAH, Доп_угли2015.ekib, Доп_угли2015.maikub, Станции2015.KARAG, Станции2015.KAN, Доп_угли2015.nazar, Доп_угли2015.ibor, Доп_угли2015.berez, Доп_угли2015.per, Доп_угли2015.irbei, Доп_угли2015.kansk, Станции2015.TUNG, Доп_угли2015.jer, Доп_угли2015.karab, Станции2015.IRKUT, Доп_угли2015.azey, Доп_угли2015.mug, Доп_угли2015.cher, Станции2015.HAK, Станции2015.TUV, Станции2015.BUR, Доп_угли2015.gusin, Доп_угли2015.tugn, Доп_угли2015.okino, Станции2015.CHIT, Доп_угли2015.har, Доп_угли2015.urt, Доп_угли2015.tataur, Доп_угли2015.tarbag, Доп_угли2015.zab_kam, Станции2015.YAKUT, Доп_угли2015.neru, Доп_угли2015.zyryan, Доп_угли2015.pyak, Станции2015.AMUR, Доп_угли2015.rai, Доп_угли2015.erk, Станции2015.URG, Станции2015.USHUM, Станции2015.PRIM, Доп_угли2015.bikin, Доп_угли2015.razdol, Доп_угли2015.hankai, Станции2015.MAG, Станции2015.SAH, Станции2015.KAMCH, Станции2015.CHUKOT, Доп_угли2015.anad, Доп_угли2015.bering, Станции2015.QOTR, Станции2015.SNK, Станции2015.EWTP, Станции2015.NT, Станции2015.OBOR, Станции2015.VED, Станции2015.OBL, Станции2015.DEP, Станции2015.OES, Станции2015.ER, Станции2015.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2015.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor=Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2015 LEFT JOIN Доп_угли2015 ON (Станции2015.YEAR=Доп_угли2015.YEAR) AND (Станции2015.NUMB1120=Доп_угли2015.NUMB1120)) ON Имена_ОЭС.oes=Станции2015.OES) ON Имена_областей.OBL=Станции2015.OBL) ON Имена_станций.NUMB=Станции2015.NUMB1120) LEFT JOIN имена_ГК ON Станции2015.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2015.BE=имена_БЕ.code;
